@testitem "random assignments agree with a dense vector" begin
    using Random
    rng = MersenneTwister(8)
    bad = Ref{Any}(nothing)
    for T in (Int, Float32)
        for _ in 1:100
            n = rand(rng, 1:15)
            s = SparseVec{T}(n); d = zeros(T, n)
            for _ in 1:30
                i = rand(rng, 1:n); x = rand(rng, T[0, 0, 1, 2, 3])
                s[i] = x; d[i] = x
            end
            if (collect(s), nnz(s)) != (d, count(!iszero, d))
                bad[] = (T, collect(s), nnz(s), d)
                break
            end
        end
        isnothing(bad[]) || break
    end
    @test isnothing(bad[])
end

@testitem "sparse_dot agrees with the dense dot" begin
    using Random
    rng = MersenneTwister(9)
    bad = Ref{Any}(nothing)
    for _ in 1:200
        n = rand(rng, 1:20)
        a = SparseVec{Int}(n); b = SparseVec{Int}(n)
        foreach(_ -> (a[rand(rng, 1:n)] = rand(rng, -3:3)), 1:8)
        foreach(_ -> (b[rand(rng, 1:n)] = rand(rng, -3:3)), 1:8)
        sparse_dot(a, b) == sum(collect(a) .* collect(b)) || (bad[] = (collect(a), collect(b)); break)
    end
    @test isnothing(bad[])
    @test sparse_dot(SparseVec{Float32}(3), SparseVec{Float32}(3)) isa Float32
    @test_throws DimensionMismatch sparse_dot(SparseVec{Int}(2), SparseVec{Int}(3))
end

