@testitem "fills then overwrites the oldest" begin
    r = RingBuffer{Int}(3)
    @test isempty(r)
    push!(r, 1); push!(r, 2)
    @test collect(r) == [1, 2]
    push!(r, 3); push!(r, 4)
    @test collect(r) == [2, 3, 4]
    @test r[1] == 2 && r[end] == 4
end

@testitem "random pushes agree with a Vector model" begin
    using Random
    rng = MersenneTwister(2)
    bad = Ref{Any}(nothing)
    for cap in (1, 2, 5, 8)
        r = RingBuffer{Int}(cap); model = Int[]
        for _ in 1:100
            x = rand(rng, -9:9)
            push!(r, x); push!(model, x)
            length(model) > cap && popfirst!(model)
            if collect(r) != model
                bad[] = (cap, collect(r), copy(model))
                break
            end
        end
    end
    @test isnothing(bad[])
end

@testitem "String elements and errors" begin
    r = RingBuffer{String}(2)
    push!(r, "été"); push!(r, "日本"); push!(r, "ñ")
    @test collect(r) == ["日本", "ñ"]
    @test eltype(r) == String
    @test_throws BoundsError r[3]
    @test_throws BoundsError r[0]
    @test_throws "capacity must be at least 1" RingBuffer{Int}(0)
end

