@testitem "successful writes, new and replacing" begin
    mktempdir() do dir
        p = joinpath(dir, "out.txt")
        @test atomic_write(io -> print(io, "héllo 日本\n"), p) == p
        @test read(p, String) == "héllo 日本\n"
