@testitem "a throwing f keeps the old file and leaves no temp files" begin
    mktempdir() do dir
        p = joinpath(dir, "keep.txt")
        write(p, "original ✓")
        @test_throws "writer failed" atomic_write(p) do io
            print(io, "partial")
            error("writer failed")
        end
        @test read(p, String) == "original ✓"
        @test readdir(dir) == ["keep.txt"]
        q = joinpath(dir, "new.txt")
        @test_throws "boom" atomic_write(io -> error("boom"), q)
        @test !ispath(q)
        @test readdir(dir) == ["keep.txt"]
    end
end

@testitem "missing directory" begin
    mktempdir() do dir
        @test_throws SystemError atomic_write(io -> print(io, "x"), joinpath(dir, "no", "such", "file.txt"))
    end
end

