@testitem "concurrent increments are not lost" begin
    d = LockedDict{String,Int}()
    inc(x) = (yield(); x + 1)
    tasks = [Threads.@spawn(for _ in 1:200
                                update!(inc, d, "日本", 0)
                            end) for _ in 1:8]
    foreach(wait, tasks)
    @test get(d, "日本", 0) == 1600
    @test length(d) == 1
end

@testitem "different keys and snapshots" begin
    d = LockedDict{Int,Vector{Int}}()
    @test update!(v -> push!(copy(v), 1), d, 1, Int[]) == [1]
    update!(v -> push!(copy(v), 2), d, 1, Int[])
    update!(v -> v, d, 2, [9])
    s = snapshot(d)
    @test s == Dict(1 => [1, 2], 2 => [9])
    s[3] = [0]
    @test length(d) == 2
    @test get(d, 7, :none) === :none
end

@testitem "a throwing f leaves the old value" begin
    d = LockedDict{String,Int}()
    update!(x -> x + 5, d, "k", 0)
    @test_throws "bad update" update!(x -> error("bad update"), d, "k", 0)
    @test get(d, "k", -1) == 5
    update!(x -> x + 1, d, "k", 0)
    @test get(d, "k", -1) == 6
end

