@testitem "small examples and empty graph" begin
    @test topo_order(0, Tuple{Int,Int}[]) == Int[]
    o = topo_order(4, [(1, 2), (2, 3), (1, 3)])
    @test sort(o) == 1:4
    @test findfirst(==(1), o) < findfirst(==(2), o) < findfirst(==(3), o)
