@testitem "random DAGs give valid permutations" begin
    using Random
    rng = MersenneTwister(3)
    bad = Ref{Any}(nothing)
    for _ in 1:300
        n = rand(rng, 1:12)
        perm = randperm(rng, n)
        edges = Tuple{Int,Int}[]
        for _ in 1:rand(rng, 0:20)
            a, b = rand(rng, 1:n), rand(rng, 1:n)
            a == b && continue
            push!(edges, (perm[min(a, b)], perm[max(a, b)]))
        end
        o = topo_order(n, edges)
        pos = invperm(o)
        if !(sort(o) == 1:n && all(pos[u] < pos[v] for (u, v) in edges))
            bad[] = (n, edges, o)
            break
        end
    end
    @test isnothing(bad[])
end

