    @test_throws "graph has a cycle" topo_order(3, [(1, 2), (2, 3), (3, 1)])
    @test_throws "graph has a cycle" topo_order(2, [(2, 2)])
    @test_throws "outside 1:3" topo_order(3, [(1, 4)])
    @test_throws ArgumentError topo_order(-1, Tuple{Int,Int}[])
end

@testitem "long chain is linear time" begin
    n = 100_000
    edges = [(i, i + 1) for i in 1:n-1]
    t = @elapsed o = topo_order(n, edges)
    @test o == 1:n
    @test t < 1
end

