@testitem "exact for linear functions and matches a naive sum" begin
    using Random
    g = collect(range(0, 2; length = 11))
    @test cumtrapz(g, 3 .* g .+ 1) ≈ 1.5 .* g .^ 2 .+ g
    rng = MersenneTwister(1)
    for _ in 1:100
        n = rand(rng, 1:30)
        x = cumsum(rand(rng, n) .+ 0.1)
        y = randn(rng, n)
        ref = [sum((x[i] - x[i-1]) * (y[i] + y[i-1]) / 2 for i in 2:k; init = 0.0) for k in 1:n]
        @test cumtrapz(x, y) ≈ ref
    end
end

@testitem "generic axes and element types" begin
    using OffsetArrays
    x = OffsetArray([0.0, 1.0, 2.0, 4.0], -1:2)
    y = OffsetArray([1.0, 1.0, 1.0, 1.0], -1:2)
    r = cumtrapz(x, y)
    @test axes(r) == axes(y)
    @test collect(r) == [0.0, 1.0, 2.0, 4.0]
    @test cumtrapz(view([9.0, 0.0, 1.0, 2.0], 2:4), view([9.0, 2.0, 2.0, 2.0], 2:4)) == [0.0, 2.0, 4.0]
