@testitem "matches a two-pass reference on random data" begin
    using Random
    rng = MersenneTwister(1)
    for scale in (1.0, 1e3), offset in (0.0, 1e9)
        x = offset .+ scale .* randn(rng, 1000)
        r = RunningStat()
        foreach(v -> push!(r, v), x)
        m = sum(big.(x)) / length(x)
        v = sum((big.(x) .- m) .^ 2) / (length(x) - 1)
        @test count(r) == 1000
        @test mean(r) ≈ Float64(m) rtol = 1e-12
        @test variance(r) ≈ Float64(v) rtol = 1e-6
    end
end

@testitem "merge equals a single pass" begin
    using Random
    rng = MersenneTwister(2)
    x = 1e9 .+ randn(rng, 600)
    a, b, whole = RunningStat(), RunningStat(), RunningStat()
    foreach(v -> push!(a, v), x[1:250])
    foreach(v -> push!(b, v), x[251:end])
    foreach(v -> push!(whole, v), x)
