@testitem "random strings agree with brute force" begin
    using Random
    rng = MersenneTwister(1)
    function brute(s)
        c = collect(s); n = length(c)
        best = 1:0
        for i in 1:n, j in i:n
            sub = c[i:j]
            sub == reverse(sub) && length(sub) > length(best) && (best = i:j)
        end
        return String(c[best])
    end
    alphabet = collect("abé日")
