@testitem "round trips over the whole range" begin
    using Random
    rng = MersenneTwister(1)
    vals = [rand(rng, UInt64, 500); UInt64[0, 1, 127, 128, UInt64(2)^32, UInt64(2)^63, typemax(UInt64)];
            [rand(rng, UInt64) >> rand(rng, 0:63) for _ in 1:500]]
    bad = Ref{Any}(nothing)
    for v in vals
        enc = encode_varint(v)
        dec = decode_varint(enc)
        dec == (v, length(enc) + 1) || (bad[] = (v, enc, dec); break)
    end
    @test isnothing(bad[])
    stream = reduce(vcat, encode_varint.(vals))
    function decode_all(stream)
        pos = 1; got = UInt64[]
        while pos <= length(stream)
            v, pos = decode_varint(stream, pos)
            push!(got, v)
        end
        return got
    end
    @test decode_all(stream) == vals
end

