@testitem "random words agree with a Set" begin
    using Random
    rng = MersenneTwister(5)
    alphabet = collect("abé日")
    bad = Ref{Any}(nothing)
    for _ in 1:200
        words = [String(rand(rng, alphabet, rand(rng, 0:4))) for _ in 1:rand(rng, 0:30)]
        t = Trie(); ref = Set{String}()
        for w in words
            push!(t, w); push!(ref, w)
        end
        for p in [String(rand(rng, alphabet, rand(rng, 0:3))) for _ in 1:5]
            got = (length(t), count_prefix(t, p), p in t)
            want = (length(ref), count(startswith(w, p) for w in ref), p in ref)
            if got != want
                bad[] = (words, p, got, want)
                break
            end
        end
        isnothing(bad[]) || break
    end
    @test isnothing(bad[])
end

