@testitem "random strings agree with pair deletion" begin
    using Random
    # Oracle: delete adjacent matched pairs until nothing changes; balanced iff only
    # non-bracket characters remain. No stack, no indexing.
    function oracle(s)
        t = filter(in("()[]{}"), s)
        while true
            u = replace(t, "()" => "", "[]" => "", "{}" => "")
            u == t && return isempty(t)
            t = u
        end
    end
    rng = MersenneTwister(3)
    alphabet = collect("()[]{}ñ日a")
    for _ in 1:3000
        s = String(rand(rng, alphabet, rand(rng, 0:12)))
        @test balanced(s) == oracle(s)
    end
end

